 <?php $__env->startSection('title',$student->exists?'Edit Student':'Add Student'); ?> <?php $__env->startSection('page-title','Student Details'); ?> <?php $__env->startSection('content'); ?>
<div class="form-page"><form class="panel form-card" method="post" action="<?php echo e($student->exists?route('students.update',$student):route('students.store')); ?>"><?php echo csrf_field(); ?> <?php if($student->exists): ?><?php echo method_field('PUT'); ?><?php endif; ?><h1><?php echo e($student->exists?'Edit':'Add'); ?> Student</h1><p>Student details can be linked to written answer papers.</p><div class="form-grid"><label>Student name<input class="input" name="name" value="<?php echo e(old('name',$student->name)); ?>" required></label><label>Roll number<input class="input" name="roll_number" value="<?php echo e(old('roll_number',$student->roll_number)); ?>"></label><label class="span-2">Grade/Class<input class="input" name="grade" value="<?php echo e(old('grade',$student->grade)); ?>"></label><?php if(auth()->user()->hasFeature('parent_details')): ?><label>Parent name<input class="input" name="parent_name" value="<?php echo e(old('parent_name',$student->parent_name)); ?>"></label><label>Parent email<input class="input" type="email" name="parent_email" value="<?php echo e(old('parent_email',$student->parent_email)); ?>"></label><label>Parent mobile<input class="input" name="parent_mobile" value="<?php echo e(old('parent_mobile',$student->parent_mobile)); ?>"></label><label>Alternate contact<input class="input" name="alternate_contact" value="<?php echo e(old('alternate_contact',$student->alternate_contact)); ?>"></label><?php else: ?><div class="info-note span-2">Parent email and mobile are available only in Mode 3.</div><?php endif; ?></div><div class="form-actions"><a class="btn ghost" href="<?php echo e(route('students.index')); ?>">Cancel</a><button class="btn">Save Student</button></div></form></div><?php $__env->stopSection(); ?>
